{{ config(schema='silver', materialized='view', tags=['file_feed', 'healthcare.provider_roster', 'generated']) }}

-- Silver: every accepted row of every healthcare.provider_roster file, typed by the contract.
with deliveries as (
    select distinct on (d.file_sha256)
        d.file_sha256,
        d.source_key,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) as file_date,
        d.received_at
    from {{ source('ops', 'intake_delivery') }} as d
    where d.feed = 'healthcare.provider_roster'
    order by
        d.file_sha256,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) desc,
        d.received_at desc,
        d.source_key desc
)

select
    b.file_sha256,
    b.row_number,
    d.source_key,
    d.file_date,
    d.received_at,
    f.contract_version,
    b.record ->> 'npi' as "npi",
    b.record ->> 'provider_first_name' as "provider_first_name",
    b.record ->> 'provider_last_name' as "provider_last_name",
    b.record ->> 'taxonomy_code' as "taxonomy_code",
    b.record ->> 'practice_state' as "practice_state",
    b.record ->> 'accepting_new_patients' as "accepting_new_patients",
    (b.record ->> 'effective_date')::date as "effective_date"
from {{ source('bronze', 'csv_record') }} as b
inner join {{ source('ops', 'intake_file') }} as f
    on f.feed = b.feed and f.file_sha256 = b.file_sha256
inner join deliveries as d on d.file_sha256 = b.file_sha256
where b.feed = 'healthcare.provider_roster'
